story_bible_lock:
These are immutable anchors for the full session. They must stay consistent in every node:
- Child name: {{Child_Name}}
- Child age: {{Child_Age}}
- Target behavior: {{Target_Behavior}}
- Main character seed: {{Main_Character}}
- Story setting seed: {{Setting}}
- Emotional tone: {{Emotional_Tone}}

output_schema:
{
  "node_text": "String (setup + question. Max 2 sentences)",
  "visual_style": "String (fixed style for entire story)",
  "character_anchor": "String (fixed character identity: type/species + colors + distinctive trait)",
  "visual_context": "String (must include: visual_style + character_anchor + established setting + current action)",
  "choices": [
    { "choice_text": "Positive action", "behavior_type": "Positive" },
    { "choice_text": "Negative action", "behavior_type": "Negative" }
  ]
}
